    'c.newcolleague': { m: "اعرض العمل خطوة خطوة", f: "اعرضي العمل خطوة خطوة", x: "عرض العمل خطوة خطوة" }, // nieuw, nalezen
    'c.newcolleague.b': { m: "ما كان صعباً عليك في أسابيعك الأولى صعب على الزميل الجديد أيضاً. اشرح العمل بخطوات صغيرة: أولاً هذا، ثم ذاك. لا تتكلم أسرع أو بصوت أعلى: أرِه العمل، ودعه يفعله بعدك. لا تسأل «Snap je het?»: كثير من الناس يقولون نعم، حتى عندما لا يفهمون. قل بدلاً من ذلك «Laat eens zien»، وراقب. أخبره أين توجد الأشياء، مثل المرحاض والمقصف والقفازات. كن صبوراً (geduld): التعلّم يأخذ وقتاً، عند الجميع.", f: "ما كان صعباً عليكِ في أسابيعك الأولى صعب على الزميل الجديد أيضاً. اشرحي العمل بخطوات صغيرة: أولاً هذا، ثم ذاك. لا تتكلمي أسرع أو بصوت أعلى: أريه العمل، ودعيه يفعله بعدك. لا تسألي «Snap je het?»: كثير من الناس يقولون نعم، حتى عندما لا يفهمون. قولي بدلاً من ذلك «Laat eens zien»، وراقبي. أخبريه أين توجد الأشياء، مثل المرحاض والمقصف والقفازات. كوني صبورة (geduld): التعلّم يأخذ وقتاً، عند الجميع.", x: "ما كان صعباً في الأسابيع الأولى صعب على الزميل الجديد أيضاً. الشرح يكون بخطوات صغيرة: أولاً هذا، ثم ذاك. لا حاجة للكلام أسرع أو بصوت أعلى: الأفضل عرض العمل، ثم تركه يفعله بعد ذلك. السؤال «Snap je het?» لا يكفي: كثير من الناس يقولون نعم، حتى عندما لا يفهمون. الأفضل قول «Laat eens zien»، والمراقبة. من المفيد ذكر أماكن الأشياء، مثل المرحاض والمقصف والقفازات. الصبر (geduld) مهم: التعلّم يأخذ وقتاً، عند الجميع." }, // nieuw, nalezen
    'c.newcolleague.p': "أحسنت! والآن الخطوة التالية.", // nieuw, nalezen
    'c.newcolleague.s': { m: "تشرح مهمة لزميل جديد. يقول: «Ja, ja, ik snap het.» ماذا تفعل؟", f: "تشرحين مهمة لزميل جديد. يقول: «Ja, ja, ik snap het.» ماذا تفعلين؟", x: "شرح مهمة لزميل جديد. يقول: «Ja, ja, ik snap het.» ما التصرف الصحيح؟" }, // nieuw, nalezen
    'c.newcolleague.o1': { m: "قل «Laat eens zien»، وراقبه وهو يقوم بها.", f: "قولي «Laat eens zien»، وراقبيه وهو يقوم بها.", x: "قول «Laat eens zien»، ومراقبته وهو يقوم بها." }, // nieuw, nalezen
    'c.newcolleague.o2': { m: "قل «Goed zo»، وارجع إلى عملك.", f: "قولي «Goed zo»، وارجعي إلى عملك.", x: "قول «Goed zo»، والرجوع إلى العمل الخاص." }, // nieuw, nalezen
    'c.newcolleague.o3': { m: "اشرح كل شيء مرة أخرى، أسرع وبصوت أعلى.", f: "اشرحي كل شيء مرة أخرى، أسرع وبصوت أعلى.", x: "شرح كل شيء مرة أخرى، أسرع وبصوت أعلى." }, // nieuw, nalezen
    'c.newcolleague.w': "كثير من الناس يقولون «ja»، حتى عندما لم يفهموا. عندما يُريك ذلك، تريان كلاكما إن كان الأمر يعمل. هذا أسرع من إصلاح خطأ لاحقاً.", // nieuw, nalezen
